limits={'orderbook':'Static synthetic book; no cancellations, hidden liquidity or latency.','amm':'Two-token constant-product model; no arbitrage path, MEV or fee-income forecast.','hedge':'GBM paths and discrete rebalancing; no volatility surface, jumps or real execution.','risk':'Synthetic stationary returns; tail estimates depend on the assumed distribution.','contagion':'Stylized fixed liabilities and pro-rata clearing; no liquidity runs or fire sales.','auctions':'Independent uniform private values and risk-neutral bidders; no collusion or entry costs.'}
def enrich(raw):
 for model,(finding,scale) in findings.items():
  # Insert after each project question, before the expandable method notes.
  pattern=r'(<article[^>]*>.*?href="https://lab\.yourcatalyst\.in/experiments/#'+model+r'".*?)(<details\s)'
  extra=takeaway('SEEDED MODEL EXAMPLE / SEED 42',finding)+f'<p class="research-scope"><strong>Limitations</strong> · {limits[model]}</p>'+f'<p class="stack-line"><strong>Stack</strong> JavaScript ES modules · SVG · node:test · GitHub Pages</p><p class="scale-line"><strong>Computation</strong> {scale}</p><p class="evidence-link"><a href="evidence/experiment-results.json">Exact parameters &amp; outputs ↗</a></p>'
  raw=re.sub(pattern,lambda m:m.group(1)+extra+m.group(2),raw,count=1,flags=re.S)
 return raw

def wrap(raw,title,depth=0,interactive=False):
 raw=raw.replace('<!-- wp:html -->','').replace('<!-- /wp:html -->','')
 if depth==0:
  raw=raw.replace('width: 100vw;','width: 100%;').replace('left: 50%;','left: 0;').replace('margin-left: -50vw;','margin: 0;').replace('margin-right: -50vw;','')
 prefix='../'*depth or './'
 raw=re.sub(r'>Maths &(?:amp;)? code</a', '>Finance notebook</a', raw, count=1).replace('href="https://lab.yourcatalyst.in/experiments/learn.html"','href="https://lab.yourcatalyst.in/experiments/"',1)
 for old,new in [('href="/"',f'href="{prefix}"'),('href="/projects/"',f'href="{prefix}projects/"'),('href="/aboutme/"',f'href="{prefix}aboutme/"')]:raw=raw.replace(old,new)
 for folder in ['artifacts','evidence']:
  raw=raw.replace(f'href="{folder}/',f'href="{prefix}{folder}/')
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Quantitative mechanism design and market audits. Reproducible matching, governance and finance experiments with explicit assumptions, source code and benchmark evidence."><meta name="theme-color" content="#172b24"><title>{title} · Your Catalyst</title><link rel="icon" href="{prefix}assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/site.css"><script type="module" src="{prefix}assets/site.mjs"></script></head><body><a class="skip-link" href="#page-content">Skip to content</a><main id="page-content">{raw}</main></body></html>'''
